def parse_csv_line(line):
    """Parse one line of CSV into a list of field strings."""
    if line == '':
        return ['']
    fields = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == '"':
            # quoted field: runs to closing quote
            i += 1  # skip opening quote
            field_chars = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # two double quotes → one literal double quote
                        field_chars.append('"')
                        i += 2
                    else:
                        # closing quote found
                        i += 1
                        # after closing quote must be comma or end of line
                        if i < n and line[i] == ',':
                            i += 1
                        elif i == n:
                            pass  # end of line, fine
                        else:
                            raise ValueError(
                                f"Expected comma or end of line after closing quote, got {line[i]!r}"
                            )
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            else:
                # reached end of line without closing quote
                raise ValueError("Unquoted field has no closing quote")
            fields.append(''.join(field_chars))
        else:
            # unquoted field: runs until comma or end of line
            # must not contain double quote
            j = line.find(',', i)
            if j == -1:
                # no more commas: rest of line is this field
                field_str = line[i:]
                if '"' in field_str:
                    raise ValueError("Double quote in unquoted field")
                fields.append(field_str)
                i = n
            else:
                field_str = line[i:j]
                if '"' in field_str:
                    raise ValueError("Double quote in unquoted field")
                fields.append(field_str)
                i = j + 1
    return fields


